var nameResult = ValidateName(user.Name);
var emailResult = ValidateEmail(user.Email);
var userResult = ResultApplicative.Apply(nameResult, emailResult, (name, email) => new User(name, email));

var userResult = ResultApplicative.Validate(
    () => new User(name, email, age),
    ValidateName(name),
    ValidateEmail(email),
    ValidateAge(age)
);

var userResult = ValidateName(name)
    .ApplyWith(ValidateEmail(email), (n, e) => new User(n, e))
    .ApplyWith(ValidateAge(age), (user, age) => user with { Age = age });

Task<Result<User>> userTask = GetUserAsync(id)
    .TapAsync(user => LogUserAccessAsync(user.Id))
    .TapAsync(user => CacheUserAsync(user));

var userIds = new[] { 1, 2, 3 };
Task<Result<IEnumerable<User>>> usersTask = 
    ResultAsync.TraverseAsync(userIds, LoadUserAsync);

var userIds = new[] { 1, 2, 3 };
var userResults = userIds.Select(LoadUser);
Result<IEnumerable<User>> allUsers = ResultCollections.Sequence(userResults);

// Gateway observable to Result stream
var subscription = gatewayObservable.ToResultStream(
    onNext: result => {
        if (result.IsSuccess)
            ProcessGatewayData(result.Value);
        else
            LogGatewayError(result.Errors);
    }
);

// Validate gateway data stream
gatewayDataStream.SelectResult(
    selector: data => ValidateGatewayData(data),
    onNext: result => ProcessValidatedData(result)
);

// Process only valid gateway messages
gatewayMessages.WhereSuccess(
    selector: msg => ValidateMessage(msg),
    onSuccess: validMsg => ProcessValidMessage(validMsg)
);

// Handle gateway results with separate paths
gatewayStream.HandleResults(
    selector: data => ProcessGatewayData(data),
    onSuccess: result => UpdateDatabase(result),
    onFailure: errors => LogErrors(errors)
);

// Collect gateway batch with timeout
var batchResult = await gatewayBatchStream.CollectResults(
    timeout: TimeSpan.FromSeconds(30),
    cancellationToken: ct
);

if (batchResult.IsSuccess)
    ProcessBatch(batchResult.Value);

// Route gateway results to different processors
var successSubject = ResultSubscriptionsCore.CreateResultSubject<Order>();
var failureSubject = ResultSubscriptionsCore.CreateResultSubject<Error>();

gatewayResultStream.RouteResults(successSubject, failureSubject);

// Create replay bridge for gateway configuration
var configBridge = gatewayConfigStream.CreateReplayBridge(bufferSize: 10);

// Multiple subscribers get the same cached configs
configBridge.Subscribe(onSuccess: config => Service1.Configure(config));
configBridge.Subscribe(onSuccess: config => Service2.Configure(config));

var subject = ResultSubscriptionsCore.CreateResultSubject<User>();
var subscription = subject.Subscribe(
    onSuccess: user => Console.WriteLine($"User: {user.Name}"),
    onFailure: errors => Console.WriteLine($"Error: {string.Join(", ", errors)}")
);

subject.OnNext(Result<User>.Success(new User("John")));
subject.OnNext(Result<User>.WithFailure("User not found"));

using var subscriptions = ResultSubscriptionsCore.CreateSubscriptionManager();

subscriptions.Add(subject1.Subscribe(onSuccess: HandleUser));
subscriptions.Add(subject2.Subscribe(onSuccess: HandleOrder));
// All subscriptions disposed when manager is disposed

remarks.code:
// Success results
var success = Result.Success();
var successWithValue = Result<string>.Success("Hello World");

// Failure results
var failure = Result.WithFailure("Operation failed");
var failureWithValue = Result<int>.WithFailure("Parse error", defaultValue: 0);

// Multiple errors
var multipleErrors = Result.WithFailure(new[] { "Error 1", "Error 2" });

// Warnings (successful with diagnostics)
var withWarnings = Result<string>.WithWarnings(
    new[] { "Performance warning" },
    "Operation completed"
);
